"""Complete dashboard HTML and CSS template."""
HTML_TEMPLATE = '<!DOCTYPE html>\n<html lang="en">\n<head>\n    <meta charset="UTF-8">\n\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n    <title>StoryPool Dashboard - {machine}</title>\n    <style>\n        :root {{\n            --bg: #0d1117;\n            --card-bg: #161b22;\n            --border: #30363d;\n            --text: #c9d1d9;\n            --text-muted: #8b949e;\n            --accent: #58a6ff;\n            --success: #3fb950;\n            --warning: #d29922;\n            --error: #f85149;\n            --shadow: #010409;\n        }}\n        * {{ box-sizing: border-box; margin: 0; padding: 0; }}\n        body {{\n            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif;\n            background: var(--bg);\n            color: var(--text);\n            line-height: 1.5;\n            padding: 1rem;\n        }}\n        .header {{\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            flex-wrap: wrap;\n            gap: .5rem;\n            margin-bottom: 1.5rem;\n            padding-bottom: 1rem;\n            border-bottom: 1px solid var(--border);\n        }}\n        .header h1 {{\n            font-size: 1.5rem;\n            font-weight: 600;\n        }}\n        .mode-badge {{\n            padding: 0.25rem 0.75rem;\n            border-radius: 1rem;\n            font-size: 0.75rem;\n            font-weight: 600;\n            text-transform: uppercase;\n        }}\n        .mode-live {{ background: var(--success); color: var(--bg); }}\n        .mode-shadow {{ background: var(--warning); color: var(--bg); }}\n        .grid {{\n            display: grid;\n            grid-template-columns: repeat(auto-fit, minmax(min(100%, 350px), 1fr));\n            gap: 1rem;\n        }}\n        .card {{\n            min-width: 0;\n            overflow-wrap: anywhere;\n            background: var(--card-bg);\n            border: 1px solid var(--border);\n            border-radius: 6px;\n            padding: 1rem;\n        }}\n        .card-title {{\n            font-size: 0.875rem;\n            font-weight: 600;\n            color: var(--text-muted);\n            text-transform: uppercase;\n            letter-spacing: 0.05em;\n            margin-bottom: 0.75rem;\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n        }}\n        .card-full {{ grid-column: 1 / -1; }}\n        table {{\n            width: 100%;\n            table-layout: fixed;\n            overflow-wrap: anywhere;\n            border-collapse: collapse;\n            font-size: 0.875rem;\n        }}\n        th, td {{\n            padding: 0.5rem;\n            text-align: left;\n            border-bottom: 1px solid var(--border);\n        }}\n        th {{\n            color: var(--text-muted);\n            font-weight: 500;\n        }}\n        tr:last-child td {{ border-bottom: none; }}\n        .status {{\n            display: inline-block;\n            width: 8px;\n            height: 8px;\n            border-radius: 50%;\n            margin-right: 0.5rem;\n        }}\n        .status-running {{ background: var(--success); }}\n        .status-stopped {{ background: var(--warning); }}\n        .status-error {{ background: var(--error); }}\n        .status-unknown {{ background: var(--text-muted); }}\n        .badge {{\n            display: inline-block;\n            padding: 0.125rem 0.5rem;\n            border-radius: 1rem;\n            font-size: 0.75rem;\n            font-weight: 500;\n        }}\n        .badge-pass {{ background: rgba(63, 185, 80, 0.2); color: var(--success); }}\n        .badge-fail {{ background: rgba(248, 81, 73, 0.2); color: var(--error); }}\n        .badge-pending {{ background: rgba(210, 153, 34, 0.2); color: var(--warning); }}\n        .badge-ok {{ background: rgba(63, 185, 80, 0.2); color: var(--success); }}\n        .badge-warning {{ background: rgba(210, 153, 34, 0.2); color: var(--warning); }}\n        .badge-capped {{ background: rgba(248, 81, 73, 0.2); color: var(--error); }}\n        .badge-conserve {{ background: rgba(139, 148, 158, 0.2); color: var(--text-muted); }}\n        .metric {{\n            display: flex;\n            justify-content: space-between;\n            padding: 0.5rem 0;\n            border-bottom: 1px solid var(--border);\n        }}\n        .metric:last-child {{ border-bottom: none; }}\n        .metric-label {{ color: var(--text-muted); }}\n        .metric-value {{ font-weight: 600; font-family: monospace; }}\n        .metric-delta {{\n            font-size: 0.75rem;\n            margin-left: 0.5rem;\n        }}\n        .delta-up {{ color: var(--success); }}\n        .delta-down {{ color: var(--error); }}\n        .progress-bar {{\n            height: 6px;\n            background: var(--border);\n            border-radius: 3px;\n            overflow: hidden;\n            margin-top: 0.25rem;\n        }}\n        .progress-fill {{\n            height: 100%;\n            border-radius: 3px;\n            transition: width 0.3s;\n        }}\n        .progress-ok {{ background: var(--success); }}\n        .progress-warning {{ background: var(--warning); }}\n        .progress-error {{ background: var(--error); }}\n        .alert {{\n            background: rgba(248, 81, 73, 0.1);\n            border: 1px solid var(--error);\n            border-radius: 6px;\n            padding: 1rem;\n            margin-bottom: 1rem;\n        }}\n        .alert-title {{\n            font-weight: 600;\n            color: var(--error);\n            margin-bottom: 0.5rem;\n        }}\n        a {{\n            color: var(--accent);\n            text-decoration: none;\n        }}\n        a:hover {{ text-decoration: underline; }}\n        .timestamp {{\n            font-size: 0.75rem;\n            color: var(--text-muted);\n        }}\n        .empty-state {{\n            text-align: center;\n            padding: 2rem;\n            color: var(--text-muted);\n        }}\n        .truncate {{\n            max-width: 200px;\n            overflow: hidden;\n            text-overflow: ellipsis;\n            white-space: nowrap;\n        }}\n    </style>\n</head>\n<body>\n    <div class="header">\n        <h1>StoryPool Dashboard</h1>\n        <div>\n            <span class="mode-badge mode-{mode_class}">{mode}</span>\n            <span class="timestamp">Updated: {timestamp} (engine auto-refresh 3s)</span>\n        </div>\n    </div>\n    \n    {alerts}\n    \n    <div class="grid">\n        {services_card}\n        {guards_card}\n        {merges_card}\n        {providers_card}\n        {scorecard_card}\n        {backlog_card}\n        {verdicts_card}\n        {fix_attempts_card}\n        {watchdog_card}\n    </div>\n</body>\n</html>\n'
